import {
  SchemaDocument,
  TypeDefinition,
  TypeNode,
} from '../ir/types';

/**
 * Generates idiomatic Swift Codable & Sendable structs and enums.
 */
export function generateSwift(doc: SchemaDocument): string {
  const lines: string[] = [
    '// Code generated by TypeBridge. DO NOT EDIT.',
    'import Foundation',
    '',
  ];

  for (const def of doc.definitions) {
    if (def.kind === 'struct') {
      lines.push(generateSwiftStruct(def));
      lines.push('');
    } else if (def.kind === 'enum') {
      lines.push(generateSwiftEnum(def));
      lines.push('');
    } else if (def.kind === 'alias') {
      lines.push(`public typealias ${def.name} = ${mapTypeToSwift(def.targetType)}`);
      lines.push('');
    }
  }

  return lines.join('\n');
}

function generateSwiftStruct(def: Extract<TypeDefinition, { kind: 'struct' }>): string {
  const lines: string[] = [];
  if (def.description) {
    lines.push(`/// ${def.description}`);
  }
  lines.push(`public struct ${def.name}: Codable, Sendable {`);

  const codingKeys: Array<{ swiftName: string; rawName: string }> = [];

  for (const field of def.fields) {
    const swiftName = toCamelCase(field.name);
    const swiftType = mapTypeToSwift(field.type);
    const opt = field.optional ? '?' : '';

    if (swiftName !== field.name) {
      codingKeys.push({ swiftName, rawName: field.name });
    }

    if (field.description) {
      lines.push(`    /// ${field.description}`);
    }
    if (field.deprecated) {
      lines.push('    @available(*, deprecated)');
    }
    lines.push(`    public let ${swiftName}: ${swiftType}${opt}`);
  }

  if (codingKeys.length > 0) {
    lines.push('');
    lines.push('    enum CodingKeys: String, CodingKey {');
    for (const field of def.fields) {
      const swiftName = toCamelCase(field.name);
      if (swiftName !== field.name) {
        lines.push(`        case ${swiftName} = "${field.name}"`);
      } else {
        lines.push(`        case ${swiftName}`);
      }
    }
    lines.push('    }');
  }

  lines.push('}');
  return lines.join('\n');
}

function generateSwiftEnum(def: Extract<TypeDefinition, { kind: 'enum' }>): string {
  const lines: string[] = [];
  if (def.description) {
    lines.push(`/// ${def.description}`);
  }
  const isNumeric = def.values.length > 0 && typeof def.values[0].value === 'number';
  const rawType = isNumeric ? 'Int' : 'String';
  lines.push(`public enum ${def.name}: ${rawType}, Codable, Sendable {`);

  for (const val of def.values) {
    const caseName = toCamelCase(val.name.toLowerCase());
    const rawVal = isNumeric ? val.value : `"${val.value}"`;
    lines.push(`    case ${caseName} = ${rawVal}`);
  }

  lines.push('}');
  return lines.join('\n');
}

function mapTypeToSwift(node: TypeNode): string {
  switch (node.kind) {
    case 'primitive':
      switch (node.primitive) {
        case 'string':
          return 'String';
        case 'date':
          return 'Date';
        case 'uuid':
          return 'UUID';
        case 'number':
          return 'Double';
        case 'integer':
          return 'Int';
        case 'boolean':
          return 'Bool';
        case 'null':
        case 'any':
        default:
          return 'String';
      }
    case 'reference':
      return node.name;
    case 'array':
      return `[${mapTypeToSwift(node.elementType)}]`;
    case 'map':
      return `[${mapTypeToSwift(node.keyType)}: ${mapTypeToSwift(node.valueType)}]`;
    case 'optional':
      return `${mapTypeToSwift(node.innerType)}?`;
    case 'union':
      return 'String';
    case 'literal':
      return typeof node.value === 'string' ? 'String' : typeof node.value === 'number' ? 'Double' : 'Bool';
    default:
      return 'String';
  }
}

function toCamelCase(str: string): string {
  return str.replace(/[-_](\w)/g, (_, c) => c.toUpperCase());
}
